def merge_small(chunks, min_chars=100):
merged = []
for c in chunks:
if merged and len(merged[-1]["text"]) < min_chars and merged[-1]["source"] == c["source"]:
c = {**c, "text": merged.pop()["text"] + "\n" + c["text"]}
merged.append(c)
